<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';import type {EChartsOption} from 'echarts'
import PageHeader from '@/components/PageHeader.vue';import LoadingState from '@/components/LoadingState.vue';import EmptyState from '@/components/EmptyState.vue';import ErrorState from '@/components/ErrorState.vue';import BaseChart from '@/components/BaseChart.vue';import StatusTag from '@/components/StatusTag.vue'
import {useSiteStore} from '@/stores/site';import {scenariosApi} from '@/api/scenarios';import {simulationApi} from '@/api/simulation';import {reportsApi} from '@/api/reports';import {carbonApi} from '@/api/carbon';import {recommendationsApi} from '@/api/recommendations';import {carbonMarketApi} from '@/api/carbonMarket';import {risksApi} from '@/api/risks'
import type {CarbonAccountingRun,CarbonCostAssessment,RecommendationRun,ReportFile,ReportStatus,ReportTask,RiskAssessment,Scenario,ScenarioVersion,SimulationBatch} from '@/types'
const route=useRoute(),siteStore=useSiteStore(),loading=ref(true),busy=ref(false),error=ref<string|null>(null),operationError=ref<string|null>(null);const scenarios=ref<Scenario[]>([]),versions=ref<ScenarioVersion[]>([]),batches=ref<SimulationBatch[]>([]),reports=ref<ReportTask[]>([]),selected=ref<ReportTask|null>(null),versionId=ref<number|null>(null),taskId=ref<number|null>(null),title=ref('碳中和可行性与风险评估报告'),formats=ref<('DOCX'|'PDF')[]>(['DOCX','PDF']);const accountingRuns=ref<CarbonAccountingRun[]>([]),recommendationRuns=ref<RecommendationRun[]>([]),marketAssessments=ref<CarbonCostAssessment[]>([]),riskRuns=ref<RiskAssessment[]>([]),historyStatus=ref<ReportStatus|null>(null),historyDates=ref<[Date,Date]|null>(null);const b={get id(){return batches.value.find(batch=>batch.items.some(item=>item.task_id===taskId.value))?.id}}
type Dict=Record<string,unknown>;const dict=(v:unknown):Dict=>v&&typeof v==='object'&&!Array.isArray(v)?v as Dict:{};const arr=(v:unknown):unknown[]=>Array.isArray(v)?v:[];const num=(v:unknown):number|null=>typeof v==='number'?v:null;const data=computed(()=>dict(selected.value?.report_data_json));const input=computed(()=>dict(selected.value?.input_snapshot_json));const scenarioName=(version:number)=>{const v=versions.value.find(x=>x.id===version);return scenarios.value.find(x=>x.id===v?.scenario_id)?.name||`Version #${version}`};const tasks=computed(()=>batches.value.flatMap(b=>b.items).filter(i=>i.scenario_version_id===versionId.value&&i.task_id).map(i=>({id:i.task_id!,batchId:b.id,label:`Task #${i.task_id} · ${i.status}`})).filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i));const selectedTask=computed(()=>tasks.value.find(x=>x.id===taskId.value));const currentScenario=computed(()=>{const v=versions.value.find(x=>x.id===versionId.value);return scenarios.value.find(x=>x.id===v?.scenario_id)});const latestAccounting=computed(()=>accountingRuns.value[0]);const latestRecommendation=computed(()=>recommendationRuns.value[0]);const marketAssessment=computed(()=>marketAssessments.value.find(x=>x.scenario_version_id===versionId.value&&x.task_id===taskId.value));const riskAssessment=computed(()=>riskRuns.value.find(x=>x.scenario_version_id===versionId.value&&x.simulation_task_id===taskId.value));const reportNumber=(id:number)=>`CN-RPT-${String(id).padStart(6,'0')}`;const size=(v:number)=>v<1024?`${v} B`:v<1048576?`${(v/1024).toFixed(1)} KB`:`${(v/1048576).toFixed(1)} MB`;const display=(v:unknown)=>v==null?'暂无数据':typeof v==='object'?JSON.stringify(v):String(v)
const sections=computed(()=>[{name:'项目基本情况',value:data.value.project},{name:'能源情况',value:data.value.energy_and_devices},{name:'碳核算',value:data.value.carbon_accounting},{name:'目标',value:input.value.scenario_version},{name:'路径推荐',value:data.value.path_recommendations},{name:'多场景推演',value:data.value.scenario_analysis},{name:'碳市场',value:data.value.carbon_market},{name:'CCER / 绿证',value:input.value.carbon_market},{name:'经济性',value:data.value.scenario_analysis},{name:'风险',value:data.value.risk_assessment},{name:'可行性结论',value:data.value.conclusions},{name:'实施建议',value:data.value.implementation_recommendations}])
const accounting=computed(()=>dict(data.value.carbon_accounting)),accountingSummary=computed(()=>dict(accounting.value.summary)),scenarioAnalysis=computed(()=>dict(data.value.scenario_analysis)),comparison=computed(()=>dict(scenarioAnalysis.value.comparison_json)),comparisonItems=computed(()=>arr(comparison.value.items).map(dict)),marketRows=computed(()=>arr(data.value.carbon_market).map(dict)),riskRows=computed(()=>arr(data.value.risk_assessment).map(dict));const objectChart=(obj:Dict,name:string,type:'bar'|'pie'='bar'):EChartsOption=>type==='pie'?{series:[{name,type:'pie',radius:['35%','68%'],data:Object.entries(obj).filter(([,v])=>typeof v==='number').map(([k,v])=>({name:k,value:v as number}))}]}:{xAxis:{type:'category',data:Object.keys(obj)},yAxis:{type:'value'},series:[{name,type:'bar',data:Object.values(obj).map(num)}]};const annualOption=computed(()=>objectChart(dict(accountingSummary.value.annual_emissions),'年度碳排')),energyOption=computed(()=>objectChart(dict(accountingSummary.value.by_energy),'能源碳排','pie')),scopeOption=computed(()=>objectChart(dict(accountingSummary.value.by_scope),'Scope','pie'));const compareChart=(key:string,name:string):EChartsOption=>({xAxis:{type:'category',data:comparisonItems.value.map(x=>`V#${x.scenario_version_id}`)},yAxis:{type:'value'},series:[{name,type:'bar',data:comparisonItems.value.map(x=>num(x[key]))}]});const carbonOption=computed(()=>compareChart('cumulative_carbon_emission_t','累计碳排')),reductionOption=computed(()=>compareChart('cumulative_carbon_reduction_t','累计减排')),economyOption=computed(()=>compareChart('total_electricity_cost','总电费')),renewableOption=computed(()=>compareChart('renewable_generation_kwh','可再生能源'));const marketOption=computed<EChartsOption>(()=>({xAxis:{type:'category',data:marketRows.value.map(x=>`Assessment #${x.id}`)},yAxis:{type:'value'},series:[{name:'综合碳成本',type:'bar',data:marketRows.value.map(x=>num(dict(x.result).comprehensive_carbon_cost))}]}));const riskOption=computed<EChartsOption>(()=>{const levels:Record<string,number>={LOW:1,MEDIUM:2,HIGH:3};const results=riskRows.value.flatMap(x=>arr(x.results).map(dict));return{xAxis:{type:'category',data:results.map(x=>String(x.category))},yAxis:{type:'value',min:0,max:3,interval:1},series:[{name:'风险等级',type:'bar',data:results.map(x=>levels[String(x.level)]??null)}]}})
async function initialize(){loading.value=true;error.value=null;try{await siteStore.loadSites();if(!siteStore.currentSite)return;const enterpriseId=siteStore.currentSite.enterprise_id;[scenarios.value,batches.value,accountingRuns.value,recommendationRuns.value,marketAssessments.value,riskRuns.value]=await Promise.all([scenariosApi.list(enterpriseId),simulationApi.batches(enterpriseId),carbonApi.runs({enterprise_id:enterpriseId}),recommendationsApi.list(enterpriseId),carbonMarketApi.assessments(),risksApi.list()]);versions.value=(await Promise.all(scenarios.value.map(s=>scenariosApi.versions(s.id)))).flat();versionId.value=Number(route.query.scenario_version)||versions.value.at(-1)?.id||null;taskId.value=Number(route.query.task)||tasks.value[0]?.id||null;await loadReports();selected.value=reports.value[0]||null}catch(e){error.value=(e as {message?:string}).message||'报告中心加载失败'}finally{loading.value=false}}
async function loadReports(){if(!siteStore.currentSite)return;const [start,end]=historyDates.value||[];reports.value=await reportsApi.list({site_id:siteStore.currentSite.id,status:historyStatus.value||undefined,start:start?.toISOString(),end:end?.toISOString()})}
async function createReport(){if(!versionId.value||!taskId.value||!siteStore.currentSite)return;busy.value=true;operationError.value=null;try{selected.value=await reportsApi.create({enterprise_id:siteStore.currentSite.enterprise_id,scenario_version_id:versionId.value,simulation_task_id:taskId.value,title:title.value,batch_id:selectedTask.value?.batchId,accounting_run_id:latestAccounting.value?.id,recommendation_run_id:latestRecommendation.value?.id});reports.value=[selected.value,...reports.value]}catch(e){operationError.value=(e as {message?:string}).message||'报告创建失败'}finally{busy.value=false}}
async function selectReport(row:ReportTask){busy.value=true;try{selected.value=await reportsApi.get(row.id)}catch(e){operationError.value=(e as {message?:string}).message||'报告详情加载失败'}finally{busy.value=false}}
async function render(){if(!selected.value||!formats.value.length)return;busy.value=true;operationError.value=null;try{await reportsApi.render(selected.value.id,formats.value);selected.value=await reportsApi.get(selected.value.id);reports.value=reports.value.map(x=>x.id===selected.value!.id?selected.value!:x)}catch(e){operationError.value=(e as {message?:string}).message||'报告渲染失败';selected.value=await reportsApi.get(selected.value.id).catch(()=>selected.value)}finally{busy.value=false}}
async function download(file:ReportFile){if(!selected.value)return;try{const blob=await reportsApi.download(selected.value.id,file.format),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.file_name;a.click();URL.revokeObjectURL(url)}catch(e){operationError.value=(e as {message?:string}).message||'文件下载失败'}}
watch(versionId,()=>taskId.value=tasks.value[0]?.id||null);onMounted(initialize)
</script>
<template><section><PageHeader kicker="REPORT CENTER" title="碳中和可行性与风险评估报告" description="创建、预览并渲染基于唯一冻结快照的正式 DOCX/PDF 报告。"><el-button :loading="loading" @click="initialize">刷新</el-button></PageHeader><LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" @retry="initialize"/><template v-else-if="siteStore.currentSite"><div class="report-layout"><main><article class="panel"><div class="panel-head"><div><span>CREATE REPORT</span><h2>报告创建</h2></div><el-button type="primary" :loading="busy" :disabled="!versionId||!taskId" @click="createReport">冻结快照并创建报告</el-button></div><div class="report-form"><label>Site<el-input :model-value="siteStore.currentSite.name" disabled/></label><label>ScenarioVersion<el-select v-model="versionId"><el-option v-for="v in versions" :key="v.id" :value="v.id" :label="`${scenarioName(v.id)} · V${v.version_number} · #${v.id}`"/></el-select></label><label>SimulationTask<el-select v-model="taskId"><el-option v-for="t in tasks" :key="t.id" :value="t.id" :label="t.label"/></el-select></label><label>报告标题<el-input v-model="title"/></label></div><h3>创建输入摘要</h3><div class="input-summary"><div><span>项目/企业</span><b>{{siteStore.currentSite.name}} / #{{siteStore.currentSite.enterprise_id}}</b></div><div><span>场景</span><b>{{currentScenario?.name||'缺失'}}</b></div><div><span>仿真任务</span><b>{{taskId?`#${taskId}`:'缺失'}}</b></div><div><span>数据时间范围</span><b>{{versions.find(x=>x.id===versionId)?.parameter_snapshot_json.start_year??'缺失'}}—{{versions.find(x=>x.id===versionId)?.parameter_snapshot_json.end_year??'缺失'}}</b></div><div><span>碳核算结果</span><b>{{latestAccounting?latestAccounting.status:'缺失'}}</b></div><div><span>推荐结果</span><b>{{latestRecommendation?'已存在':'缺失'}}</b></div><div><span>碳市场评估</span><b>{{marketAssessment?'已完成':'缺失'}}</b></div><div><span>风险评估</span><b>{{riskAssessment?'已完成':'缺失'}}</b></div></div><el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/></article>
<template v-if="selected"><article class="panel report-detail"><div class="panel-head"><div><span>{{reportNumber(selected.id)}}</span><h2>{{selected.title}}</h2></div><StatusTag :status="selected.status"/></div><div class="report-meta"><span>Report #{{selected.id}}</span><span>创建 {{new Date(selected.created_at).toLocaleString('zh-CN')}}</span><span>生成 {{selected.generated_at?new Date(selected.generated_at).toLocaleString('zh-CN'):'尚未生成'}}</span><span>Snapshot {{new Date(selected.snapshot_created_at).toLocaleString('zh-CN')}}</span></div><el-alert v-if="selected.status==='FAILED'" :title="selected.failure_reason||'报告生成失败'" type="error" :closable="false"/><div class="render-bar"><el-checkbox-group v-model="formats"><el-checkbox value="DOCX">DOCX</el-checkbox><el-checkbox value="PDF">PDF</el-checkbox></el-checkbox-group><el-button type="primary" :loading="busy" :disabled="!formats.length" @click="render">渲染所选格式</el-button><span>不创建新快照，不显示伪造进度</span></div></article><article class="panel"><div class="panel-head"><div><span>REPORT FILES</span><h2>DOCX / PDF 文件</h2></div></div><el-table v-if="selected.files.length" :data="selected.files"><el-table-column prop="format" label="格式"/><el-table-column prop="file_name" label="文件名"/><el-table-column label="大小"><template #default="{row}">{{size(row.file_size)}}</template></el-table-column><el-table-column prop="checksum" label="SHA-256" min-width="300"/><el-table-column label="生成时间"><template #default="{row}">{{new Date(row.generated_at).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="下载"><template #default="{row}"><el-button link @click="download(row)">下载 {{row.format==='DOCX'?'Word':'PDF'}}</el-button></template></el-table-column></el-table><EmptyState v-else title="报告尚未渲染" description="选择 DOCX、PDF 或两种格式进行渲染"/></article><article class="panel trace-chain"><h2>追溯链</h2><div><b>{{siteStore.currentSite.name}}</b><span>↓</span><b>{{scenarioName(selected.scenario_version_id)}}</b><span>↓</span><b>ScenarioVersion #{{selected.scenario_version_id}}</b><span>↓</span><b>SimulationTask #{{selected.simulation_task_id}}</b><span>↓</span><b>Carbon Market / Risk</b><span>↓</span><b>ReportSnapshot</b><span>↓</span><b>{{selected.files.map(x=>x.format).join(' / ')||'尚未渲染'}}</b></div><el-alert title="报告内容基于创建时冻结快照，后续源数据变化不会修改历史报告。" type="info" :closable="false"/></article><article class="panel"><div class="panel-head"><div><span>SNAPSHOT PREVIEW</span><h2>结构化章节预览</h2></div><el-tag>仅使用 report_snapshot</el-tag></div><el-collapse><el-collapse-item v-for="section in sections" :key="section.name" :title="section.name"><EmptyState v-if="section.value==null" title="该章节快照数据缺失"/><pre v-else>{{JSON.stringify(section.value,null,2)}}</pre></el-collapse-item></el-collapse></article><section class="report-chart-grid"><article class="panel"><h3>年度碳排趋势</h3><BaseChart :option="annualOption" :empty="!Object.keys(dict(accountingSummary.annual_emissions)).length"/></article><article class="panel"><h3>能源碳排构成</h3><BaseChart :option="energyOption" :empty="!Object.keys(dict(accountingSummary.by_energy)).length"/></article><article class="panel"><h3>Scope 构成</h3><BaseChart :option="scopeOption" :empty="!Object.keys(dict(accountingSummary.by_scope)).length"/></article><article class="panel"><h3>多场景碳排</h3><BaseChart :option="carbonOption" :empty="!comparisonItems.length"/></article><article class="panel"><h3>多场景累计减排</h3><BaseChart :option="reductionOption" :empty="!comparisonItems.length"/></article><article class="panel"><h3>经济性</h3><BaseChart :option="economyOption" :empty="!comparisonItems.length"/></article><article class="panel"><h3>可再生能源</h3><BaseChart :option="renewableOption" :empty="!comparisonItems.length"/></article><article class="panel"><h3>碳市场</h3><BaseChart :option="marketOption" :empty="!marketRows.length"/></article><article class="panel"><h3>风险分布</h3><BaseChart :option="riskOption" :empty="!riskRows.length"/></article></section></template><EmptyState v-else title="暂无报告，可从场景或仿真结果创建"/></main><aside class="panel report-history"><div class="panel-head"><div><span>HISTORY</span><h2>历史报告</h2></div></div><el-select v-model="historyStatus" clearable placeholder="全部状态" @change="loadReports"><el-option v-for="s in ['PENDING','GENERATING','SUCCESS','FAILED']" :key="s" :value="s" :label="s"/></el-select><el-date-picker v-model="historyDates" type="datetimerange" @change="loadReports"/><EmptyState v-if="!reports.length" title="暂无报告"/><button v-for="r in reports" :key="r.id" :class="{active:selected?.id===r.id}" @click="selectReport(r)"><strong>{{reportNumber(r.id)}}</strong><StatusTag :status="r.status"/><span>{{scenarioName(r.scenario_version_id)}} · V#{{r.scenario_version_id}} · Task #{{r.simulation_task_id}}</span><small>{{new Date(r.created_at).toLocaleString('zh-CN')}} · DOCX {{r.files.some(x=>x.format==='DOCX')?'可下载':'—'}} / PDF {{r.files.some(x=>x.format==='PDF')?'可下载':'—'}}</small></button></aside></div></template><EmptyState v-else title="暂无 Site"/></section></template>
